package com.fathom.liability; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.math.BigDecimal; import java.time.*; import java.util.*; import org.springframework.web.bind.annotation.*;
@RestController public class LiabilityController { private final LiabilityRepository repo; public LiabilityController(LiabilityRepository repo){this.repo=repo;} record Req(@NotNull LiabilityType liabilityType,@NotBlank String name,String lender,String currency,@DecimalMin("0.0") BigDecimal principalAmount,@NotNull @DecimalMin("0.0") BigDecimal outstandingAmount,BigDecimal interestRate,BigDecimal emiAmount,LocalDate startDate,LocalDate endDate){} record Res(UUID id,UUID userId,LiabilityType liabilityType,String name,BigDecimal outstandingAmount,boolean active,Instant createdAt,Instant updatedAt){}
@PostMapping("/api/users/{userId}/liabilities") Res create(@PathVariable UUID userId,@Valid @RequestBody Req r){ Liability l=new Liability(); l.setUserId(userId); l.setLiabilityType(r.liabilityType()); l.setName(r.name()); l.setLender(r.lender()); if(r.currency()!=null)l.setCurrency(r.currency()); l.setPrincipalAmount(r.principalAmount()); l.setOutstandingAmount(r.outstandingAmount()); l.setInterestRate(r.interestRate()); l.setEmiAmount(r.emiAmount()); l.setStartDate(r.startDate()); l.setEndDate(r.endDate()); return m(repo.save(l)); }
@GetMapping("/api/users/{userId}/liabilities") List<Res> list(@PathVariable UUID userId){ return repo.findByUserId(userId).stream().map(this::m).toList(); }
private Res m(Liability l){return new Res(l.getId(),l.getUserId(),l.getLiabilityType(),l.getName(),l.getOutstandingAmount(),l.isActive(),l.getCreatedAt(),l.getUpdatedAt());}}
